WITH exploded AS (SELECT id, service, level, status_code, key, v FROM app_logs LATERAL VIEW EXPLODE(context) e AS key, v) SELECT level, CASE WHEN status_code >= 462 THEN 'LARGE' ELSE 'SMALL' END AS status_code_tier, APPROX_PERCENTILE(status_code, ARRAY(0.25, 0.5, 0.75)) AS status_code_quartiles, SUM(CASE WHEN service = 'billing' THEN status_code ELSE 0 END) AS billing_status_code, COUNT(*) FILTER (WHERE key = 'version') AS version_rows FROM exploded GROUP BY level, CASE WHEN status_code >= 462 THEN 'LARGE' ELSE 'SMALL' END HAVING COUNT(*) FILTER (WHERE key = 'version') < 1 ORDER BY version_rows DESC NULLS FIRST
